const input = items[0]?.json || {};

return [
  {
    json: {
      ...input,
      dry_run: input.dry_run === undefined ? true : input.dry_run,
      limit: Number(input.limit || 1),
      profile: input.profile || 'feminino',
      marketplace: input.marketplace || 'shopee',
      target: input.target || 'teste-whatsapp',
      allowed_targets_csv: input.allowed_targets_csv || 'teste-whatsapp',
      channel_adapter: input.channel_adapter || 'whatsapp',
      run_id: input.run_id || new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19) + '-mvp-supabase',
    },
  },
];

const item = items[0].json;
const cleanText = (value, field) => {
  const text = String(value || '').trim();
  if (!/^[a-z0-9][a-z0-9_-]{1,80}$/i.test(text)) {
    throw new Error(`${field} fora do contrato MVP: ${text}`);
  }
  return text;
};
const profile = cleanText(item.profile, 'profile');
const marketplace = cleanText(item.marketplace, 'marketplace');
const target = cleanText(item.target, 'target');
const channelAdapter = cleanText(item.channel_adapter, 'channel_adapter');
const limit = Number(item.limit || 1);
if (!Number.isInteger(limit) || limit < 1 || limit > 20) {
  throw new Error(`limit fora do contrato MVP: ${item.limit}`);
}
const dryRun = item.dry_run === true || item.dry_run === 'true' || item.dry_run === 1 || item.dry_run === '1';
const allowedTargets = String(item.allowed_targets_csv || '')
  .split(',')
  .map((targetItem) => targetItem.trim())
  .filter(Boolean);
if (allowedTargets.length === 0) {
  throw new Error('allowed_targets_csv obrigatorio');
}
const artifactGeneratedAt = item.artifact_generated_at || new Date().toISOString();
const sqlText = (value) => `'${String(value).replace(/'/g, "''")}'`;
const rankingQuery = `select
  profile,
  marketplace,
  stable_key,
  item_id,
  product_name,
  offer_link,
  price,
  reference_price,
  rating,
  sales_count,
  primary_subniche,
  commercial_score,
  score_reasons,
  rank_profile,
  rank_subniche
from offers.v_offer_ranking_current
where is_eligible = true
  and profile = ${sqlText(profile)}
  and marketplace = ${sqlText(marketplace)}
order by
  rank_profile nulls last,
  commercial_score desc,
  sales_count desc,
  rating desc nulls last,
  item_id
limit ${limit};`;
return [{
  json: {
    ...item,
    profile,
    marketplace,
    target,
    channel_adapter: channelAdapter,
    limit,
    dry_run: dryRun,
    allowed_targets: allowedTargets,
    artifact_generated_at: artifactGeneratedAt,
    ranking_query: rankingQuery,
  }
}];

const context = $('Validar Contexto').first().json;
const formatMoney = (value) => {
  if (value === null || value === undefined || value === '') return 'nao informado';
  const numberValue = Number(value);
  if (Number.isFinite(numberValue)) return numberValue.toFixed(2).replace('.', ',');
  return String(value);
};
return items.map((item, index) => {
  const offer = item.json;
  const messageText = `${offer.product_name}\n\nPreco: R$ ${formatMoney(offer.price)}\nAvaliacao: ${offer.rating ?? 'nao informada'}\n\nLink: ${offer.offer_link}\n\nAviso: este link pode gerar comissao de afiliado. Preco e disponibilidade podem mudar.`;
  return {
    json: {
      ...context,
      ...offer,
      manifest_item_number: index + 1,
      message_text: messageText,
      manifest_created_at: new Date().toISOString(),
    }
  };
});

const item = $json;
const allowed = new Set(item.allowed_targets || []);
const targetAllowed = allowed.has(item.target);
const blockedReason = targetAllowed ? null : 'target_not_allowlisted';
const deliveryStatus = targetAllowed ? (item.dry_run ? 'cancelled' : 'confirmed') : 'cancelled';
return {
  json: {
    ...item,
    target_allowed: targetAllowed,
    blocked_reason: blockedReason,
    delivery_status: deliveryStatus,
  }
};

const item = $json;

return {
  json: {
    ...item,
    send_result:
      item.target_allowed && !item.dry_run
        ? 'ready_for_real_channel_node'
        : item.target_allowed
          ? 'dry_run_not_sent'
          : 'blocked_by_allowlist',
    sent_at: item.dry_run ? null : new Date().toISOString(),
  },
};
